import{t as e}from"./chunks/ThreePanel.BddHBCcE.js";import{G as t,H as n,U as r,tt as i}from"./chunks/framework.DF4UzXOs.js";var a=JSON.parse(`{"title":"DirectX e Metal","description":"As APIs gráficas de baixo nível da Microsoft (DirectX 12 / DXR) e da Apple (Metal 3 / MetalKit) para jogos e aplicações de alta performance.","frontmatter":{"title":"DirectX e Metal","sidebar_label":"DirectX & Metal","description":"As APIs gráficas de baixo nível da Microsoft (DirectX 12 / DXR) e da Apple (Metal 3 / MetalKit) para jogos e aplicações de alta performance."},"headers":[],"relativePath":"directx-metal.md","filePath":"directx-metal.md","lastUpdated":0}`),o=Object.assign({name:`directx-metal.md`},{setup(a){return(a,o)=>(i(),n(`div`,null,[o[0]||=r(`<h1 id="directx-e-metal" tabindex="-1">DirectX e Metal <a class="header-anchor" href="#directx-e-metal" aria-label="Permalink to “DirectX e Metal”">​</a></h1><blockquote><p>Enquanto <strong>OpenGL</strong> e <strong>Vulkan</strong> são padrões abertos multiplataforma geridos pelo Khronos Group, <strong>DirectX</strong> (Microsoft) e <strong>Metal</strong> (Apple) são as APIs nativas proprietárias dominantes nos sistemas operacionais Windows/Xbox e macOS/iOS.</p></blockquote><p>Tanto o DirectX 12 quanto o Metal 3 foram projetados com o mesmo objetivo moderno do Vulkan: <strong>eliminar o gargalo da CPU</strong>, oferecendo controle explícito sobre a memória da GPU, filas de comandos assíncronas e execução paralela multi-thread.</p><h2 id="demonstracao-do-pipeline-explicito" tabindex="-1">Demonstração do Pipeline Explícito <a class="header-anchor" href="#demonstracao-do-pipeline-explicito" aria-label="Permalink to “Demonstração do Pipeline Explícito”">​</a></h2><p>Nas APIs modernas como DirectX 12 e Metal, você não apenas envia chamadas de desenho; você grava comandos em <em>Command Lists</em> paralelas que são submetidas a <em>Command Queues</em> na placa de vídeo.</p>`,5),t(e,{topic:`pipeline`,title:`Fluxo de Pipeline Moderno`,subtitle:`Dados e shaders transitam pelas etapas até a geração final do frame nos buffers de exibição.`}),t(e,{topic:`sombras`,title:`Cálculo de Sombras e Luz Dinâmica`,subtitle:`Passes de renderização (Shadow Pass -> Color Pass) orquestrados explicitamente na GPU.`}),o[1]||=r(`<hr><h2 id="comparativo-as-grandes-apis-de-baixo-nivel" tabindex="-1">Comparativo: As Grandes APIs de Baixo Nível <a class="header-anchor" href="#comparativo-as-grandes-apis-de-baixo-nivel" aria-label="Permalink to “Comparativo: As Grandes APIs de Baixo Nível”">​</a></h2><table tabindex="0"><thead><tr><th>Recurso</th><th>DirectX 12 Ultimate (Microsoft)</th><th>Metal 3 (Apple)</th><th>Vulkan 1.3 (Khronos)</th></tr></thead><tbody><tr><td><strong>Plataformas</strong></td><td>Windows 10/11, Xbox Series X/S</td><td>macOS, iOS, iPadOS, visionOS</td><td>Windows, Linux, Android, Switch, macOS (via MoltenVK)</td></tr><tr><td><strong>Linguagem de Shaders</strong></td><td>HLSL (High-Level Shading Language)</td><td>MSL (Metal Shading Language, C++14)</td><td>GLSL / HLSL compilados para SPIR-V</td></tr><tr><td><strong>Ray Tracing Nativo</strong></td><td>DXR (DirectX Raytracing) Tier 1.1</td><td>Metal Ray Tracing (Intersector API)</td><td>VK_KHR_ray_tracing</td></tr><tr><td><strong>Mesh Shaders</strong></td><td>Suportado nativamente</td><td>Suportado (Object &amp; Mesh Shaders)</td><td>VK_EXT_mesh_shader</td></tr><tr><td><strong>Carregamento Rápido</strong></td><td>DirectStorage (Bypass da CPU para SSD NVMe)</td><td>Metal IO (Fast Resource Loading)</td><td>Extensões de descompressão por GPU</td></tr><tr><td><strong>Upscaling de Imagem</strong></td><td>DirectSR (Super Resolution agnóstica)</td><td>MetalFX Upscaling (Temporal &amp; Spatial)</td><td>FSR / DLSS / XeSS via extensões</td></tr></tbody></table><hr><h2 id="🎮-microsoft-directx" tabindex="-1">🎮 Microsoft DirectX <a class="header-anchor" href="#🎮-microsoft-directx" aria-label="Permalink to “🎮 Microsoft DirectX”">​</a></h2><p>O DirectX é a espinha dorsal dos jogos no ecossistema PC e consoles Xbox desde 1995.</p><h3 id="evolucao-historica" tabindex="-1">Evolução Histórica: <a class="header-anchor" href="#evolucao-historica" aria-label="Permalink to “Evolução Histórica:”">​</a></h3><ul><li><strong>DirectX 9 (2002):</strong> A era de ouro do Shader Model 2.0/3.0. Pipeline parcialmente programável.</li><li><strong>DirectX 11 (2009):</strong> Altamente estável e amplamente adotado. Introduziu multithreading básico, Tessellation e Compute Shaders. Driver abstraía quase tudo da GPU.</li><li><strong>DirectX 12 (2015):</strong> Reformulação total para arquiteturas modernas. Drivers finos, gerenciamento manual de barreiras de sincronização e alocação explícita de VRAM.</li><li><strong>DirectX 12 Ultimate (2020):</strong> Unificação dos quatro pilares modernos: <strong>DXR 1.1</strong>, <strong>Mesh Shaders</strong>, <strong>Variable Rate Shading (VRS)</strong> e <strong>Sampler Feedback</strong>.</li></ul><hr><h2 id="🍏-apple-metal" tabindex="-1">🍏 Apple Metal <a class="header-anchor" href="#🍏-apple-metal" aria-label="Permalink to “🍏 Apple Metal”">​</a></h2><p>Lançado em 2014 para substituir o OpenGL ES no iOS e mais tarde introduzido no OS X, o Metal foi a primeira grande API moderna a ir para produção, antecipando o Vulkan e o DX12.</p><h3 id="principais-destaques-do-metal" tabindex="-1">Principais Destaques do Metal: <a class="header-anchor" href="#principais-destaques-do-metal" aria-label="Permalink to “Principais Destaques do Metal:”">​</a></h3><ul><li><strong>Unificação com Apple Silicon:</strong> O Metal tira proveito da arquitetura de <strong>Memória Unificada (UMA)</strong> dos processadores M1/M2/M3/M4, onde CPU e GPU compartilham o mesmo pool de RAM sem cópias caras por barramento PCIe.</li><li><strong>Metal Performance Shaders (MPS):</strong> Primitivas ultra-otimizadas para machine learning, visão computacional e álgebra linear.</li><li><strong>Game Porting Toolkit (GPTK):</strong> Camada de tradução da Apple para converter jogos de DirectX 12 para Metal em tempo real, facilitando ports de PC para Mac.</li></ul><hr><h2 id="links-rapidos" tabindex="-1">Links Rápidos <a class="header-anchor" href="#links-rapidos" aria-label="Permalink to “Links Rápidos”">​</a></h2><ul><li><a href="https://learn.microsoft.com/windows/win32/direct3d" target="_blank" rel="noreferrer">Microsoft Learn: DirectX Graphics and Gaming</a> — documentação oficial da Microsoft</li><li><a href="https://github.com/microsoft/DirectX-Graphics-Samples" target="_blank" rel="noreferrer">DirectX Graphics Samples GitHub</a> — repositório oficial com dezenas de exemplos em D3D12 e DXR</li><li><a href="https://developer.apple.com/metal/" target="_blank" rel="noreferrer">Apple Developer: Metal Documentation</a> — documentação oficial do ecossistema Metal</li><li><a href="https://github.com/microsoft/DirectXTK12" target="_blank" rel="noreferrer">DirectX Tool Kit (DirectXTK)</a> — classes utilitárias em C++ para agilizar projetos em D3D12</li><li><a href="https://github.com/KhronosGroup/MoltenVK" target="_blank" rel="noreferrer">MoltenVK</a> — biblioteca open source que traduz chamadas Vulkan para Metal no macOS e iOS</li></ul><hr><h2 id="🚀-mega-link-dump-directx-metal" tabindex="-1">🚀 MEGA LINK DUMP - DirectX &amp; Metal <a class="header-anchor" href="#🚀-mega-link-dump-directx-metal" aria-label="Permalink to “🚀 MEGA LINK DUMP - DirectX &amp; Metal”">​</a></h2><h3 id="🖥️-microsoft-directx-11-12" tabindex="-1">🖥️ Microsoft DirectX 11 &amp; 12 <a class="header-anchor" href="#🖥️-microsoft-directx-11-12" aria-label="Permalink to “🖥️ Microsoft DirectX 11 &amp; 12”">​</a></h3><ul><li><a href="https://github.com/microsoft/DirectX-Graphics-Samples" target="_blank" rel="noreferrer">Microsoft DirectX-Graphics-Samples</a> — / <a href="https://github.com/microsoft/DirectX-Graphics-Samples" target="_blank" rel="noreferrer">GitHub</a> / <a href="https://github.com/microsoft/DirectX-Graphics-Samples/tree/master/Samples/Desktop/D3D12HelloWorld" target="_blank" rel="noreferrer">Exemplos D3D12</a> / <a href="https://github.com/microsoft/DirectX-Graphics-Samples/tree/master/Samples/Desktop/D3D12Raytracing" target="_blank" rel="noreferrer">Exemplos DXR</a></li><li><a href="https://github.com/microsoft/DirectXTK12" target="_blank" rel="noreferrer">DirectX Tool Kit for DX12</a> — / <a href="https://github.com/microsoft/DirectXTK12" target="_blank" rel="noreferrer">GitHub</a> / <a href="https://github.com/microsoft/DirectXTK12/wiki" target="_blank" rel="noreferrer">Wiki e Tutoriais</a> / <a href="https://github.com/microsoft/DirectXTK12/releases" target="_blank" rel="noreferrer">Releases</a></li><li><a href="https://github.com/microsoft/DirectXShaderCompiler" target="_blank" rel="noreferrer">DirectX Shader Compiler (DXC)</a> — compilador oficial de HLSL baseado em LLVM — / <a href="https://github.com/microsoft/DirectXShaderCompiler" target="_blank" rel="noreferrer">GitHub</a> / <a href="https://github.com/microsoft/DirectXShaderCompiler/wiki" target="_blank" rel="noreferrer">Docs</a></li><li><a href="https://github.com/microsoft/DirectStorage" target="_blank" rel="noreferrer">DirectStorage API</a> — subsistema de IO ultrarrápido para jogos modernos — / <a href="https://github.com/microsoft/DirectStorage" target="_blank" rel="noreferrer">GitHub</a> / <a href="https://learn.microsoft.com/gaming/gdk/_content/gc/system/overviews/directstorage/directstorage-overview" target="_blank" rel="noreferrer">Documentação</a></li><li><a href="https://devblogs.microsoft.com/pix/" target="_blank" rel="noreferrer">PIX on Windows</a> — o profiler e depurador de performance oficial da Microsoft para DirectX 12 — / <a href="https://devblogs.microsoft.com/pix/" target="_blank" rel="noreferrer">Blog e Download</a> / <a href="https://devblogs.microsoft.com/pix/documentation/" target="_blank" rel="noreferrer">Documentação</a></li><li><a href="https://www.d3dcoder.net/" target="_blank" rel="noreferrer">3D Game Programming with DirectX 12 (Frank Luna)</a> — o livro mais respeitado para aprendizado de D3D12 — / <a href="https://www.d3dcoder.net/" target="_blank" rel="noreferrer">Website do Autor</a> / <a href="https://github.com/d3dcoder/d3d12book" target="_blank" rel="noreferrer">Código Fonte GitHub</a></li></ul><h3 id="🍏-apple-metal-framework" tabindex="-1">🍏 Apple Metal Framework <a class="header-anchor" href="#🍏-apple-metal-framework" aria-label="Permalink to “🍏 Apple Metal Framework”">​</a></h3><ul><li><a href="https://developer.apple.com/metal/" target="_blank" rel="noreferrer">Apple Metal Portal</a> — / <a href="https://developer.apple.com/metal/" target="_blank" rel="noreferrer">Visão Geral</a> / <a href="https://developer.apple.com/documentation/metal" target="_blank" rel="noreferrer">Documentação da API</a> / <a href="https://developer.apple.com/metal/Metal-Shading-Language-Specification.pdf" target="_blank" rel="noreferrer">Metal Shading Language Spec</a></li><li><a href="https://metalbyexample.com/" target="_blank" rel="noreferrer">Metal By Example (Warren Moore)</a> — o melhor livro e guia introdutório independente para Metal — / <a href="https://metalbyexample.com/" target="_blank" rel="noreferrer">Website</a> / <a href="https://github.com/metal-by-example/sample-code" target="_blank" rel="noreferrer">Código Fonte GitHub</a></li><li><a href="https://developer.apple.com/metal/sample-code/" target="_blank" rel="noreferrer">Apple Sample Code: Metal</a> — exemplos oficiais cobrindo Ray Tracing, PBR e compute shaders — / <a href="https://developer.apple.com/metal/sample-code/" target="_blank" rel="noreferrer">Catálogo de Exemplos</a></li><li><a href="https://developer.apple.com/documentation/metalperformanceshaders" target="_blank" rel="noreferrer">Metal Performance Shaders (MPS)</a> — / <a href="https://developer.apple.com/documentation/metalperformanceshaders" target="_blank" rel="noreferrer">Guia Oficial</a> / <a href="https://developer.apple.com/documentation/metalperformanceshadersgraph" target="_blank" rel="noreferrer">Grafos MPSGraph</a></li><li><a href="https://developer.apple.com/games/" target="_blank" rel="noreferrer">Game Porting Toolkit (Apple)</a> — ferramentas para avaliação e conversão de jogos DirectX para Metal — / <a href="https://developer.apple.com/games/" target="_blank" rel="noreferrer">Portal</a> / <a href="https://developer.apple.com/download/all/?q=Game%20Porting%20Toolkit" target="_blank" rel="noreferrer">Downloads</a></li><li><a href="https://github.com/KhronosGroup/MoltenVK" target="_blank" rel="noreferrer">MoltenVK</a> — camada de compatibilidade Vulkan rodando em cima de Metal — / <a href="https://github.com/KhronosGroup/MoltenVK" target="_blank" rel="noreferrer">GitHub</a> / <a href="https://github.com/KhronosGroup/MoltenVK/blob/master/Docs/MoltenVK_Runtime_UserGuide.md" target="_blank" rel="noreferrer">User Guide</a></li></ul><h3 id="🔄-bibliotecas-de-abstracao-multiplataforma" tabindex="-1">🔄 Bibliotecas de Abstração Multiplataforma <a class="header-anchor" href="#🔄-bibliotecas-de-abstracao-multiplataforma" aria-label="Permalink to “🔄 Bibliotecas de Abstração Multiplataforma”">​</a></h3><ul><li><a href="https://github.com/bkaradzic/bgfx" target="_blank" rel="noreferrer">bgfx</a> — biblioteca C++ que abstrai DirectX 11, DirectX 12, Metal, Vulkan, OpenGL e WebGL numa única interface — / <a href="https://github.com/bkaradzic/bgfx" target="_blank" rel="noreferrer">GitHub</a> / <a href="https://bkaradzic.github.io/bgfx/" target="_blank" rel="noreferrer">Docs</a></li><li><a href="https://github.com/DiligentGraphics/DiligentEngine" target="_blank" rel="noreferrer">Diligent Engine</a> — engine gráfica moderna que unifica DX11, DX12, OpenGL, Vulkan e Metal — / <a href="https://diligentgraphics.com/" target="_blank" rel="noreferrer">Website</a> / <a href="https://github.com/DiligentGraphics/DiligentEngine" target="_blank" rel="noreferrer">GitHub</a></li><li><a href="https://github.com/floooh/sokol" target="_blank" rel="noreferrer">Sokol (sokol_gfx)</a> — headers minimalistas em C para gráficos agnósticos de API — / <a href="https://github.com/floooh/sokol" target="_blank" rel="noreferrer">GitHub</a> / <a href="https://floooh.github.io/sokol-html5/" target="_blank" rel="noreferrer">Exemplos WebAssembly</a></li></ul>`,24)]))}});export{a as __pageData,o as default};